import type { JSONContent } from "@tiptap/core";
import { Markdown as TiptapMarkdown } from "@tiptap/markdown";
import type { MarkdownExtensionOptions as TiptapMarkdownOptions } from "@tiptap/markdown";
import type { Mark, Schema } from "@tiptap/pm/model";
import { Plugin, PluginKey } from "@tiptap/pm/state";

export { copyMarkdown, downloadMarkdown, importMarkdownFile } from "./files";
export { getMarkdownSlashCommandItems } from "./slash-command-items";

export interface MarkdownOptions extends TiptapMarkdownOptions {
  pasteMarkdown: boolean;
}

const MARKDOWN_PATTERN =
  /^(#{1,6}\s|>\s|[-*+]\s|\d+\.\s|```|---\s*$|\|.+\|)|\*\*[^*]+\*\*|__[^_]+__|~~[^~]+~~|`[^`]+`|!?\[[^\]]*\]\([^)]+\)/m;

export const looksLikeMarkdown = (text: string) => MARKDOWN_PATTERN.test(text);

export const markdownPastePluginKey = new PluginKey("markdownPaste");

const compatible = (marks: Mark[], mark: Mark) =>
  marks.every(
    (other) =>
      !(other.type.excludes(mark.type) || mark.type.excludes(other.type))
  );

export const normalizeMarks = (
  schema: Schema,
  json: JSONContent
): JSONContent => {
  const marks: Mark[] = [];
  const ordered = (json.marks ?? []).toSorted(
    (a, b) =>
      Number(schema.marks[a.type]?.spec.excludes === "_") -
      Number(schema.marks[b.type]?.spec.excludes === "_")
  );
  for (const raw of ordered) {
    const mark = schema.marks[raw.type] && schema.markFromJSON(raw);
    if (mark && compatible(marks, mark)) {
      marks.push(mark);
    }
  }
  return {
    ...json,
    ...(json.marks && { marks: marks.map((mark) => mark.toJSON()) }),
    ...(json.content && {
      content: json.content.map((child) => normalizeMarks(schema, child)),
    }),
  };
};

export const Markdown = TiptapMarkdown.extend<MarkdownOptions>({
  addOptions() {
    return {
      ...(this.parent?.() as TiptapMarkdownOptions),
      pasteMarkdown: false,
    };
  },

  addProseMirrorPlugins() {
    const parent = this.parent?.() ?? [];
    if (!this.options.pasteMarkdown) {
      return parent;
    }
    const { editor } = this;
    return [
      ...parent,
      new Plugin({
        key: markdownPastePluginKey,
        props: {
          handlePaste: (view, event) => {
            const data = event.clipboardData;
            const text = data?.getData("text/plain");
            const fromCodeEditor = data?.types.includes("vscode-editor-data");
            if (
              !text ||
              !editor.markdown ||
              (data?.getData("text/html") && !fromCodeEditor) ||
              view.state.selection.$from.parent.type.spec.code ||
              !looksLikeMarkdown(text)
            ) {
              return false;
            }
            return editor.commands.insertContent(editor.markdown.parse(text));
          },
        },
      }),
    ];
  },

  onBeforeCreate(event) {
    this.parent?.(event);
    const { editor } = this;
    const manager = editor.markdown;
    if (!manager) {
      return;
    }
    const parse = manager.parse.bind(manager);
    manager.parse = (markdown) =>
      normalizeMarks(editor.schema, parse(markdown));
    const { content } = editor.options;
    if (content && typeof content === "object" && !Array.isArray(content)) {
      editor.options.content = normalizeMarks(editor.schema, content);
    }
  },
});

import type { Editor } from "@tiptap/core";

export const downloadMarkdown = (editor: Editor, filename = "document.md") => {
  const url = URL.createObjectURL(
    new Blob([editor.getMarkdown()], { type: "text/markdown" })
  );
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
};

export const copyMarkdown = (editor: Editor) =>
  navigator.clipboard.writeText(editor.getMarkdown());

export const importMarkdownFile = (editor: Editor) => {
  const input = document.createElement("input");
  input.type = "file";
  input.accept = ".md,.markdown,text/markdown,text/plain";
  input.addEventListener("change", async () => {
    const text = await input.files?.[0]?.text();
    if (text !== undefined && !editor.isDestroyed) {
      editor
        .chain()
        .focus()
        .setContent(text, { contentType: "markdown" })
        .run();
    }
  });
  input.click();
};

import type { SlashCommandItem } from "../core/types";
import { downloadMarkdown, importMarkdownFile } from "./files";

/** Import and export slash command items for the `@editorcn/block-editor` menu. */
export const getMarkdownSlashCommandItems = (
  filename = "document.md"
): SlashCommandItem[] => [
  {
    command: ({ editor, range }) => {
      editor.chain().focus().deleteRange(range).run();
      importMarkdownFile(editor);
    },
    description: "Replace the document with a .md file.",
    id: "importMarkdown",
    keywords: ["markdown", "md", "import", "upload"],
    title: "Import Markdown",
  },
  {
    command: ({ editor, range }) => {
      editor.chain().focus().deleteRange(range).run();
      downloadMarkdown(editor, filename);
    },
    description: "Download the document as a .md file.",
    id: "exportMarkdown",
    keywords: ["markdown", "md", "export", "download"],
    title: "Export Markdown",
  },
];

"use client";

import type { Editor } from "@tiptap/core";
import { Copy, FileDown, FileText, FileUp } from "lucide-react";
import { useState } from "react";

import { copyMarkdown, downloadMarkdown, importMarkdownFile } from ".";
import { useToolbar, useToolbarEditor } from "../core/context";
import { useEditorState } from "../core/editor-state";
import type { ToolbarComponentProps } from "../core/types";
import { Button } from "../ui/button";
import { DropdownMenuItem } from "../ui/dropdown-item";
import { Popover } from "../ui/popover";
import { PopoverContent } from "../ui/popover-content";

export interface MarkdownToolbarProps extends ToolbarComponentProps {
  filename?: string;
}

export const MarkdownToolbar = ({
  className,
  editor: editorProp,
  filename,
}: MarkdownToolbarProps) => {
  const { labels } = useToolbar();
  const editor = useToolbarEditor(editorProp);
  const [open, setOpen] = useState(false);

  const disabled =
    useEditorState(editor, (edit) => edit.isDestroyed || !edit.markdown) ??
    true;

  const run = (action: (target: Editor) => unknown) => {
    setOpen(false);
    if (editor && !disabled) {
      action(editor);
    }
  };

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      side="bottom"
      align="start"
      sideOffset={6}
      trigger={
        <Button
          aria-label={labels.markdown}
          className={className}
          size="icon-sm"
          disabled={disabled}
          tooltip={labels.markdown}
        >
          <FileText />
        </Button>
      }
    >
      <PopoverContent role="menu" style={{ minWidth: "11rem", padding: 4 }}>
        <DropdownMenuItem onClick={() => run(importMarkdownFile)}>
          <FileUp />
          {labels.importMarkdown}
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={() => run((target) => downloadMarkdown(target, filename))}
        >
          <FileDown />
          {labels.exportMarkdown}
        </DropdownMenuItem>
        <DropdownMenuItem onClick={() => run(copyMarkdown)}>
          <Copy />
          {labels.copyMarkdown}
        </DropdownMenuItem>
      </PopoverContent>
    </Popover>
  );
};

import * as React from "react";

import { useTooltip } from "./tooltip";
